@push('head')<link rel="stylesheet" href="{{ asset('assets/admin-master.css') }}">@endpush
@php $labels=['paket'=>'Paket Travel','driver'=>'Driver','kendaraan'=>'Kendaraan']; $pk='id_'.$resource; @endphp
<nav class="travel-tabs" aria-label="Data master">@foreach($labels as $key=>$label)<a class="{{ $resource===$key?'active':'' }}" href="{{ route('admin.'.$key.'.index') }}">{{ $label }}</a>@endforeach<a class="add" href="{{ route('admin.'.$resource.'.create') }}">+ Tambah {{ $labels[$resource] }}</a></nav>
<form class="travel-search" method="get"><input class="input" name="keyword" value="{{ $keyword ?? '' }}" placeholder="{{ $resource==='driver' ? 'Cari nama driver...' : ($resource==='kendaraan' ? 'Cari plat nomor...' : 'Cari Paket Travel...') }}" aria-label="Cari {{ $labels[$resource] }}"><button class="btn search-submit" type="submit">Cari</button>@if($resource!=='paket')<select class="input master-status-filter" aria-label="Status"><option value="">Status</option>@foreach($items->pluck('status')->unique() as $status)<option value="{{ $status }}">{{ $status }}</option>@endforeach</select>@endif</form>
<div class="travel-table-wrap"><table class="travel-table master-table master-table-{{ $resource }}"><thead><tr>@if($resource==='paket')<th>Foto &amp; Nama Paket</th><th>Tujuan</th><th>Harga</th>@elseif($resource==='driver')<th>Nama</th><th>No. Telp</th><th>No. SIM</th><th>Asal</th><th>Status</th>@else<th>Foto</th><th>No. Plat</th><th>Jenis</th><th>Merk</th><th>Kapasitas</th><th>Tahun</th><th>Status</th>@endif<th>Aksi</th></tr></thead><tbody>
@forelse($items as $item)<tr data-status="{{ $item->status ?? '' }}">@if($resource==='paket')<td><div class="travel-photo">@if(str_starts_with($item->foto_paket ?? '', 'paket/'))<img src="{{ route('katalog.foto',$item->id_paket) }}" alt="{{ $item->nama_paket }}">@elseif(str_starts_with($item->foto_paket ?? '', 'assets/img/'))<img src="{{ asset($item->foto_paket) }}" alt="{{ $item->nama_paket }}">@endif<strong>{{ $item->nama_paket }}</strong><small>{{ $item->tujuan }}</small></div></td><td>{{ $item->tujuan }}</td><td>Rp {{ number_format($item->harga,0,',','.') }}</td>@elseif($resource==='driver')<td>{{ $item->nama_lengkap }}</td><td>{{ $item->nomor_telepon }}</td><td>{{ $item->nomor_sim }}</td><td>{{ $item->alamat }}</td>@else<td>@if($item->foto_kendaraan ?? null)<img class="vehicle-photo" src="{{ Storage::disk('public')->url($item->foto_kendaraan) }}" alt="{{ $item->plat_nomor }}">@else<span aria-label="Foto belum tersedia">—</span>@endif</td><td>{{ $item->plat_nomor }}</td><td>{{ $item->jenis_kendaraan }}</td><td>{{ $item->merek }}</td><td>{{ $item->kapasitas }}</td><td>{{ $item->tahun_produksi }}</td>@endif
@if($resource!=='paket')<td><span class="master-status {{ $item->status==='Tersedia' ? 'available' : (in_array($item->status,['Bertugas','Digunakan']) ? 'busy' : 'inactive') }}">{{ $item->status }}</span></td>@endif
<td><div class="actions"><a class="btn" href="{{ route('admin.'.$resource.'.edit',$item->$pk) }}">Edit</a><button class="btn danger" type="button" data-delete-url="{{ route('admin.'.$resource.'.destroy',$item->$pk) }}" data-delete-name="{{ $resource==='paket' ? $item->nama_paket : ($resource==='driver' ? $item->nama_lengkap : $item->plat_nomor) }}">Hapus</button></div></td></tr>@empty<tr><td colspan="{{ $resource==='paket' ? 4 : ($resource==='driver' ? 6 : 8) }}">Belum ada data {{ strtolower($labels[$resource]) }}.</td></tr>@endforelse
</tbody></table></div>
<dialog class="travel-dialog" id="delete-dialog" aria-labelledby="delete-title"><h2 id="delete-title">Hapus {{ $labels[$resource] }}?</h2><p id="delete-name"></p><p>Data yang masih digunakan tidak dapat dihapus.</p><form method="post" id="delete-form">@csrf @method('DELETE')<div class="travel-actions"><button class="btn secondary" type="button" data-close-dialog>Batal</button><button class="btn danger" type="submit">Hapus</button></div></form></dialog>
@push('scripts')<script>
document.querySelectorAll('[data-delete-url]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('delete-form').action=button.dataset.deleteUrl;document.getElementById('delete-name').textContent=button.dataset.deleteName;document.getElementById('delete-dialog').showModal()}));document.querySelector('[data-close-dialog]').addEventListener('click',()=>document.getElementById('delete-dialog').close());
const statusFilter=document.querySelector('.master-status-filter');
if(statusFilter) statusFilter.addEventListener('change',()=>document.querySelectorAll('tr[data-status]').forEach(row=>row.hidden=!!statusFilter.value&&row.dataset.status!==statusFilter.value));
</script>@endpush
